#include <assert.h>
#include <stdlib.h>
#include "dk1/object_frame_layout.h"
int main(void){Dk1OwnedRom owned={0};Dk1RomImage rom;Dk1ObjectFrameLayout l;Dk1OamImage o;Dk1OamSprite s;Dk1ObjectFrameOamStyle style={0,2,3,false,false};size_t n=0;const char*p=getenv("DK1_TEST_ROM");if(!p)p="/mnt/data/Donkey Kong Country (USA) (Rev 2).sfc";assert(dk1_rom_load_file(p,&owned,&rom));assert(dk1_object_frame_layout_read(&rom,0x0330,&l));assert(l.source_pc==0xD7620Au);assert(l.large_count==2&&l.small_count==10&&l.auxiliary_count==0&&l.piece_count==12);assert(l.pieces[0].x_offset==-2&&l.pieces[0].y_offset==-28&&l.pieces[0].tile_offset==0&&l.pieces[0].group==DK1_OBJECT_FRAME_LARGE);assert(l.pieces[1].tile_offset==2);assert(l.pieces[2].tile_offset==4&&l.pieces[2].group==DK1_OBJECT_FRAME_SMALL);assert(l.pieces[11].x_offset==-20&&l.pieces[11].y_offset==-5);dk1_oam_init(&o);assert(dk1_object_frame_layout_emit_oam(&l,-128,-112,style,0,0,&o,&n));assert(n==12);assert(dk1_oam_decode_sprite(&o,0,0,&s));assert(s.x==-2&&s.y==(uint8_t)-28&&s.large&&s.width==16&&s.tile_number==0);assert(dk1_oam_decode_sprite(&o,0,2,&s));assert(s.x==-16&&s.y==(uint8_t)-2&&!s.large&&s.width==8&&s.tile_number==4);assert(dk1_object_frame_layout_signature(&l)!=0);dk1_rom_free(&owned);return 0;}
